/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isStrokeCap = require( '@stdlib/plot/vega/base/assert/is-stroke-cap' );
var join = require( '@stdlib/array/base/join' );
var strokeCaps = require( '@stdlib/plot/vega/stroke-caps' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:axis:set:gridCap' );


// MAIN //

/**
* Sets the stroke cap for axis grid lines.
*
* @private
* @param {string} value - input value
* @throws {TypeError} must be a valid stroke cap
* @returns {void}
*/
function set( value ) {
	if ( !isStrokeCap( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be one of the following: "%s". Value: `%s`.', 'gridCap', join( strokeCaps(), '", "' ), value ) );
	}
	if ( value !== this._gridCap ) {
		debug( 'Current value: %s. New value: %s.', this._gridCap, value );
		this._gridCap = value;
		this.emit( 'change' );
	}
}


// EXPORTS //

module.exports = set;
